<!DOCTYPE html>
<html lang="es">
<head>
  <meta charset="UTF-8" />
  <title>Collapse Demo</title>
</head>
<body>
  <cu-collapse id="faq" label="¿Qué es ComegenUI?" color="primary">
    <p>Una librería de componentes UI como Custom Elements nativos.</p>
  </cu-collapse>

  <cu-button onclick="toggleFaq()">Alternar FAQ</cu-button>

  <script src="dist/CuCollapse.umd.js"></script>
  <script src="dist/CuButton.umd.js"></script>
  <script>
    const faq = document.getElementById('faq');

    faq.addEventListener('toggle', (e) => {
      console.log('FAQ abierto:', e.detail);
    });

    function toggleFaq() {
      faq.toggle();
    }
  </script>
</body>
</html>
```

sections.bodyVue:
```vue
<script setup lang="ts">
import Button from "@/components/buttons/Button.vue";
import Collapse from "@/components/overlay/Collapse.vue";
import { useTemplateRef } from "vue";

const faq = useTemplateRef("faq");

function onToggle(abierto: boolean) {
  console.log("FAQ abierto:", abierto);
}

function toggleFaq() {
  faq.value?.toggle();
}
</script>

<template>
  <Collapse ref="faq" label="¿Qué es ComegenUI?" color="primary" @toggle="onToggle">
    <p>Una librería de componentes UI como Custom Elements nativos.</p>
  </Collapse>

  <Button @click="toggleFaq">Alternar FAQ</Button>
</template>
```
